'use strict'

import { marked } from 'marked'
import text from '../../../docs/rom-analysis.md'
import '../../css/rom-analysis.scss'

// The page of docs/rom-analysis.md (in the build, so it follows the document), with a contents of its sections
const content = document.querySelector('#rom-analysis')
content.innerHTML = marked.parse(text)

const slug = title => title.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
const contents = document.querySelector('#rom-analysis-contents')
const used = new Set()
for (const heading of content.querySelectorAll('h2, h3')) {
  let id = slug(heading.textContent)
  while (used.has(id)) {
    id += '-'
  }
  used.add(id)
  heading.id = id
  const link = document.createElement('a')
  link.href = `#${id}`
  link.textContent = heading.textContent
  link.className = heading.tagName.toLowerCase()
  contents.append(link)
  // Back to the top of the page from each section
  const top = document.createElement('a')
  top.href = '#'
  top.className = 'top'
  top.title = 'Haut de la page'
  top.textContent = '↑'
  heading.append(top)
}

// Wide tables scroll on their own, not the page
for (const table of content.querySelectorAll('table')) {
  const wrapper = document.createElement('div')
  wrapper.className = 'table'
  table.replaceWith(wrapper)
  wrapper.append(table)
}

// The section asked for in the address, once the ids are there
if (location.hash) {
  document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView()
}
